    code TEXT, name TEXT, field TEXT, s1 TEXT, s2 TEXT,
    r INT, i INT, a INT, s INT, e INT, c INT, pop NUMERIC, fee NUMERIC, descr TEXT, careers TEXT
) ON COMMIT DROP;

