INSERT INTO directions (code, name, field_id, first_subject_id, second_subject_id,
                        riasec_r, riasec_i, riasec_a, riasec_s, riasec_e, riasec_c, description, career_prospects)
SELECT d.code, d.name, f.id, s1.id, s2.id, d.r, d.i, d.a, d.s, d.e, d.c, d.descr, d.careers
FROM demo_dir d
JOIN fields f    ON f.code = d.field
JOIN subjects s1 ON s1.code = d.s1
JOIN subjects s2 ON s2.code = d.s2;

