CREATE TEMP TABLE demo_program ON COMMIT DROP AS
SELECT u.id AS university_id, d.id AS direction_id, x.lang, x.form, u.type, u.rating, u.region_id, dd.pop, dd.fee, dd.field, dd.code
FROM demo_offer o
JOIN universities u ON u.short_name = o.uni
CROSS JOIN LATERAL unnest(o.codes) AS c(code)
JOIN directions d ON d.code = c.code
JOIN demo_dir dd ON dd.code = c.code
CROSS JOIN LATERAL (
    SELECT l AS lang, 'FULL_TIME' AS form FROM unnest(o.langs) AS l
    UNION ALL
    SELECT 'UZ', 'PART_TIME' WHERE o.part_time AND dd.field IN ('ECONOMICS', 'EDUCATION', 'LANGUAGES', 'AGRICULTURE')
) x;

INSERT INTO programs (university_id, direction_id, language, study_form, grant_quota, contract_quota, contract_fee, duration_years)
SELECT p.university_id, p.direction_id, p.lang, p.form,
       CASE WHEN p.type <> 'STATE' OR p.form = 'PART_TIME' THEN 0
            WHEN p.lang = 'RU' THEN 5 + (p.university_id * 3 + p.direction_id) % 10
            ELSE 10 + (p.university_id * 7 + p.direction_id * 3) % 40 END,
       40 + (p.university_id * 13 + p.direction_id * 5) % 120,
       (CASE WHEN p.type <> 'STATE' THEN 38000000 + p.pop * 600000
             ELSE p.fee * 1000000
                  + CASE WHEN p.region_id = 1 THEN 2500000 ELSE 0 END
                  + CASE WHEN p.lang = 'RU' THEN 1000000 ELSE 0 END END
        * CASE WHEN p.form = 'PART_TIME' THEN 0.8 ELSE 1 END)::BIGINT,
       CASE WHEN p.field = 'MEDICINE' AND p.code <> '60910400' THEN 6 ELSE 4 END  -- clinical medicine: 6 years
FROM demo_program p;

-- ---------- Passing scores 2024–2026 ---------------------------------
-- base(2026) grant score = 52 + 0.95·rating + pop, adjusted by language/form.
-- Yearly trend per program is between −0.5 and +2.5 points (mostly rising),
-- plus small deterministic noise, so the forecast in TZ §6.3 has something to work with.
INSERT INTO passing_scores (program_id, year, grant_score, contract_score)
SELECT pr.id, y.year,
       CASE WHEN pr.grant_quota = 0 THEN NULL
            ELSE round(LEAST(186, GREATEST(56.7, b.base - (2026 - y.year) * b.trend + b.noise))::numeric, 1) END,
       round(LEAST(176, GREATEST(56.7,
             CASE WHEN u.type <> 'STATE' THEN 60 + 0.6 * u.rating + 0.5 * dd.pop - (2026 - y.year) * b.trend
                  WHEN pr.study_form = 'PART_TIME' THEN b.base - 45 - (2026 - y.year) * b.trend
                  ELSE b.base - (28 + (pr.id % 5) * 2) - (2026 - y.year) * b.trend END + b.noise))::numeric, 1)
FROM programs pr
JOIN universities u ON u.id = pr.university_id
JOIN directions d   ON d.id = pr.direction_id
JOIN demo_dir dd    ON dd.code = d.code
CROSS JOIN LATERAL (SELECT
        52 + 0.95 * u.rating + dd.pop - CASE WHEN pr.language = 'RU' THEN 6 ELSE 0 END AS base,
        ((pr.id % 4) - 0.5)::numeric AS trend,
        (((pr.id * 37) % 7) - 3) * 0.4 AS noise) b
CROSS JOIN (VALUES (2024), (2025), (2026)) AS y(year);
